{
  "findings": [
    {
      "check_id": "CKV_AZURE_112",
      "title": "Key Vault key is not HSM-backed",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key uses the software-protected RSA key type rather than an HSM-backed key type, providing weaker protection for its private key material."
    },
    {
      "check_id": "CKV_AZURE_40",
      "title": "Key Vault key has no expiration date",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key has no expiration date and can remain valid indefinitely, increasing exposure if it is not rotated or retired."
    }
  ],
  "patched_code": "variable "key_expiration_date" {
  description = "RFC 3339 expiration date for the generated Key Vault key."
  type        = string
}

resource "azurerm_key_vault_key" "generated" {
  name            = "terragoat-generated-certificate-${var.environment}"
  key_vault_id    = azurerm_key_vault.example.id
  key_type        = "RSA-HSM"
  key_size        = 2048
  expiration_date = var.key_expiration_date
  key_opts = [
    "decrypt",
    "encrypt",
    "sign",
    "unwrapKey",
    "verify",
    "wrapKey",
  ]
}
",
  "fix_summary": "Changed the key type to RSA-HSM and added a required RFC 3339 expiration-date input so deployments must explicitly define the key lifetime."
}
